def _(text):
    if LANG == "es":
        return text
    return TRANSLATIONS["en"].get(text, text)

def _f(template, *args, **kwargs):
    """Traduce una plantilla y la formatea con los argumentos dados."""
    return _(template).format(*args, **kwargs)
